import{_ as i,a0 as l,w as p,s as d,ao as s,I as a,x as e,a1 as r,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"在終端上訪問網站和下載文件 | LCTT x X-CMD","titleTemplate":false,"description":"在終端上訪問網站和下載文件 | LCTT (201404) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在終端上訪問網站和下載文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在終端上訪問網站和下載文件 | LCTT (201404) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201404/5 Command Line Tools for Downloading Files／Torrents and Browsing Websites","title":"在終端上訪問網站和下載文件","tag":"201404","desc":""},"relativePath":"201404/5 Command Line Tools for Downloading Files／Torrents and Browsing Websites.md","filePath":"[post].md"}'),g={name:"201404/5 Command Line Tools for Downloading Files／Torrents and Browsing Websites.md"};function m(w,t,c,T,h,u){const n=l("Link");return p(),d("div",null,[t[14]||(t[14]=s(`<h1 id="在終端上訪問網站和下載文件" tabindex="-1">在終端上訪問網站和下載文件 <a class="header-anchor" href="#在終端上訪問網站和下載文件" aria-label="Permalink to “在終端上訪問網站和下載文件”">​</a></h1><p>Linux 命令列工具很牛逼，Linux 命令列以及一些第三方應用讓 Linux 變得更牛逼。Linux 命令列工具可以用於下載種子和文件，可以上網衝浪。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/02/Command-Line-Internet-Tools.jpg" alt="5 Command Line Internet Tools"></p><p>本文推薦的<strong>5個強悍的上網工具</strong>方便實用，是居家旅行的必備物品。</p><h3 id="_1-rtorrent" tabindex="-1">1. rTorrent <a class="header-anchor" href="#_1-rtorrent" aria-label="Permalink to “1. rTorrent”">​</a></h3><p>rTorrent 基於文本的 Torrent 客户端，用 C++ 調製而成，我們的目標是高性能！我們可運行在標準的 Linux 發行版中，包括 FreeBSD 和 Mac OS X。</p><h4 id="安裝-rtorrent" tabindex="-1">安裝 rTorrent <a class="header-anchor" href="#安裝-rtorrent" aria-label="Permalink to “安裝 rTorrent”">​</a></h4><pre><code># apt-get install rtorrent    (基於 APT 的系統，如 Debian，Ubuntu)

# yum install rtorrent        (基於 YUM 的系統，如 RHEL，Fedora)
</code></pre><p>檢查有沒有安裝成功，運行下面命令試試：</p><pre><code># rtorrent
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/02/rTorrent.jpeg" alt="rTorrent Command Line Tool"></p><h4 id="rtorrent-的用法" tabindex="-1">rTorrent 的用法 <a class="header-anchor" href="#rtorrent-的用法" aria-label="Permalink to “rTorrent 的用法”">​</a></h4><p>下面是 rTorrent 比較常用的功能：</p><ul><li><strong>CTRL+ q</strong> – 退出 rTorrent。</li><li><strong>CTRL+ s</strong> – 開始下載。</li><li><strong>CTRL+ d</strong> – 暫停下載任務，或刪除己被暫停的下載任務。</li><li><strong>CTRL+ k</strong> – 關閉一個正在下載的任務</li><li><strong>CTRL+ r</strong> – 在開始上傳、下載之前，使用 Hash 檢查文件，確保文件的完整性。</li><li><strong>CTRL+ q</strong> – 按再次這個組合鍵，rTorrent 無條件退出。</li><li><strong>Left Arrow Key</strong> – 回退到上個頁面。</li><li><strong>Right Arrow Key</strong> – 前進到下個頁面。</li></ul><h3 id="_2-wget" tabindex="-1">2. Wget <a class="header-anchor" href="#_2-wget" aria-label="Permalink to “2. Wget”">​</a></h3><p><strong>Wget</strong> 是一個 GNU 項目，它的名稱參考了 World Wide Web (<strong>WWW</strong>)。Wget 在遞歸下載方面做得很好，你可以將整個網站的內容都下到本地，然後訪問本地的 <strong>HTML</strong> 文件。它支持多種操作系統：<strong>Windows，Mac，Linux</strong>。它支持多種協議，可通過 <strong>HTTP，HTTPS 和 FTP</strong> 下載文件。它可以對整個網站做一個鏡像（完全將目標網站的文件下載到本機），支持代理，支持斷點傳輸（即下載可暫停）。</p><h4 id="安裝-wget" tabindex="-1">安裝 Wget <a class="header-anchor" href="#安裝-wget" aria-label="Permalink to “安裝 Wget”">​</a></h4><p><strong>Wget</strong> 也是一個 GNU 項目，在標準 Linux 發行版中都有內置，就是説你不用下載安裝它就可以使用了。萬一，它沒有被默認安裝，你也可以通過 <strong>APT</strong> 或 <strong>YUM</strong> 安裝。</p><pre><code># apt-get install wget    (基於 APT 的系統，如 Debian，Ubuntu)

# yum install wget        (基於 YUM 的系統，如 RHEL，Fedora)
</code></pre><h4 id="wget-的用法" tabindex="-1">Wget 的用法 <a class="header-anchor" href="#wget-的用法" aria-label="Permalink to “Wget 的用法”">​</a></h4><p>下載一個文件：</p><pre><code># wget http://www.website-name.com/file
</code></pre><p>下載整個網站：</p><pre><code># wget -r http://www.website-name.com
</code></pre><p>下載指定類型的文件（比如 PDF 和 PNG）：</p><pre><code># wget -r -A png,pdf http://www.website-name.com
</code></pre><p>下面是一張 Wget 的截圖，我們正在把 <strong>Yahoo.com</strong> 網站整個都鏡像下來。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/02/Wget.jpeg" alt="Wget Command Line File Download"></p>`,28)),a("p",null,[t[1]||(t[1]=e("關於 wget 的更多用法，參考",-1)),r(n,{href:"http://www.tecmint.com/10-wget-command-examples-in-linux/"},{default:o(()=>[...t[0]||(t[0]=[e("Wget 的10個的用法",-1)])]),_:1}),t[2]||(t[2]=e("。",-1))]),t[15]||(t[15]=s(`<h3 id="_3-curl" tabindex="-1">3. cURL <a class="header-anchor" href="#_3-curl" aria-label="Permalink to “3. cURL”">​</a></h3><p><strong>cURL</strong> 是一個客户端工具，支持多種文件傳輸協議，比如 <strong>FTP, HTTP, FTPS, TFTP, TELNET, IMAP, POP3</strong> 等等。不像 wget 等工具，cURL 只是一個單純的下載器，支持 <strong>LDAP, POP3</strong>，支持代理下載，支持斷點續傳。</p><h4 id="安裝-curl" tabindex="-1">安裝 cURL <a class="header-anchor" href="#安裝-curl" aria-label="Permalink to “安裝 cURL”">​</a></h4><p>大多數發行版都默認安裝了 cURL，如果沒有，可通過 <strong>apt</strong> 或 <strong>yum</strong> 下載：</p><pre><code># apt-get install curl    (基於 APT 的系統，如 Debian，Ubuntu)

# yum install curl        (基於 YUM 的系統，如 RHEL，Fedora)
</code></pre><h4 id="curl-基本用法" tabindex="-1">cURL 基本用法 <a class="header-anchor" href="#curl-基本用法" aria-label="Permalink to “cURL 基本用法”">​</a></h4><pre><code># curl www.tecmint.com
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/02/Curl.jpeg" alt="Curl Data Download"></p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/02/Curl-2.jpeg" alt="Curl Download"></p><h3 id="_4-w3m" tabindex="-1">4. w3m <a class="header-anchor" href="#_4-w3m" aria-label="Permalink to “4. w3m”">​</a></h3><p>W3m 是基於文本的網頁瀏覽器，使用 GPL 協議，支持 tables, frames, color, SSL 連接，支持內嵌圖片，以快速聞名。</p><h4 id="安裝-w3m" tabindex="-1">安裝 w3m <a class="header-anchor" href="#安裝-w3m" aria-label="Permalink to “安裝 w3m”">​</a></h4><p>W3m 也是大多數發行版的默認配置，也可通過 <strong>apt</strong> 或 <strong>yum</strong> 安裝。</p><pre><code># apt-get install w3m    (基於 APT 的系統，如 Debian，Ubuntu)

# yum install w3m        (基於 YUM 的系統，如 RHEL，Fedora)
</code></pre><h4 id="w3m-的基本用法" tabindex="-1">w3m 的基本用法 <a class="header-anchor" href="#w3m-的基本用法" aria-label="Permalink to “w3m 的基本用法”">​</a></h4><pre><code># w3m www.tecmint.com
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/02/w3m.jpeg" alt="w3m Text Based Web Browser"></p><h3 id="_5-elinks" tabindex="-1">5. Elinks <a class="header-anchor" href="#_5-elinks" aria-label="Permalink to “5. Elinks”">​</a></h3><p><strong>Elinks</strong> 是一個免費的基於本文的網頁瀏覽器，支持 <strong>HTTP</strong>，支持 <strong>HTTP Cookie</strong>，支持 <strong>Perl</strong> 和 <strong>Ruby</strong> 寫的腳本，支持網頁標籤，支持鼠標，可彩色顯示頁面，支持 <strong>HTTP, FTP，SMB，IPv4，IPv6</strong>。</p><h4 id="安裝-elinks" tabindex="-1">安裝 Elinks <a class="header-anchor" href="#安裝-elinks" aria-label="Permalink to “安裝 Elinks”">​</a></h4><p>大多數發行版已經默認安裝了 Elinks，如果沒有，通過 <strong>apt</strong> 或 <strong>yum</strong> 安裝。</p><pre><code># apt-get install elinks    (基於 APT 的系統，如 Debian，Ubuntu)

# yum install elinks        (基於 YUM 的系統，如 RHEL，Fedora)
</code></pre><h4 id="elinks的基本用法" tabindex="-1">Elinks的基本用法 <a class="header-anchor" href="#elinks的基本用法" aria-label="Permalink to “Elinks的基本用法”">​</a></h4><pre><code>elinks www.tecmint.com
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/02/Elinks.jpeg" alt="Elinks Command Line Web Browsing"></p><hr>`,26)),a("p",null,[t[4]||(t[4]=e("via: ",-1)),r(n,{href:"http://www.tecmint.com/command-line-tools-for-downloading-file-and-browsing-websites/"},{default:o(()=>[...t[3]||(t[3]=[e("http://www.tecmint.com/command-line-tools-for-downloading-file-and-browsing-websites/",-1)])]),_:1})]),a("p",null,[t[7]||(t[7]=e("譯者：",-1)),r(n,{href:"https://github.com/bazz2"},{default:o(()=>[...t[5]||(t[5]=[e("bazz2",-1)])]),_:1}),t[8]||(t[8]=e(" 校對：",-1)),r(n,{href:"https://github.com/%E6%A0%A1%E5%B0%8D%E8%80%85ID"},{default:o(()=>[...t[6]||(t[6]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[11]||(t[11]=e("本文由 ",-1)),r(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[9]||(t[9]=[e("LCTT",-1)])]),_:1}),t[12]||(t[12]=e(" 原創翻譯，",-1)),r(n,{href:"http://linux.cn/"},{default:o(()=>[...t[10]||(t[10]=[e("Linux中國",-1)])]),_:1}),t[13]||(t[13]=e(" 榮譽推出",-1))])])}const f=i(g,[["render",m]]);export{P as __pageData,f as default};
